using System.Linq; using common.resources; using wServer.realm.entities;
namespace wServer.realm.worlds.logic { class StarfallObservatory:World { Enemy boss; int wings; bool done; readonly int[] active; public StarfallObservatory(ProtoWorld p):base(p){var r=new System.Random(Id);active=new[]{r.Next(3),r.Next(3)}.Distinct().ToArray();if(active.Length<2)active=new[]{0,1};DungeonAnomalyService.Attach(this,DungeonAnomalyService.Roll(DungeonCodexService.All.FirstOrDefault(x=>x.Key=="StarfallObservatory"),r));} public override int EnterWorld(Entity e){var id=base.EnterWorld(e);var n=e as Enemy;if(n==null)return id;n.OnDeath+=(s,a)=>Dead(n);if(n.ObjectDesc.ObjectId=="The Parallax"){boss=n;boss.ApplyConditionEffect(ConditionEffectIndex.Invincible);}return id;} void Dead(Enemy e){if(e.ObjectDesc.ObjectId=="Constellation Wing Seal"&&++wings>=2&&boss!=null)boss.ApplyConditionEffect(ConditionEffectIndex.Invincible,0);if(e.ObjectDesc.ObjectId=="The Parallax"&&!done){done=true;DungeonAnomalyService.Cleanup(this);foreach(var p in Players.Values){MaterialVaultService.TryDeposit(p.Client.Account,"citadel_fragment",1,"parallax:"+Id+":"+p.Client.Account.AccountId);p.SendInfo("Starfall Observatory cleared. Wings: "+string.Join(",",active));}}} } }
